"""
404 FOUNDERS — Data Validator
Validates file formats, encoding, schemas, corrupted lines, empty records,
and security constraints for dataset pipelines.
"""

from __future__ import annotations

import hashlib
import json
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any, Dict, List, Optional, Set, Union


@dataclass
class ValidationReport:
    """Report generated by dataset validation."""

    is_valid: bool
    total_records: int
    valid_records: int
    invalid_records: int
    errors: List[str] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)
    file_checksum: str = ""

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


class DataValidator:
    """Validates files and records to ensure data integrity and security."""

    ALLOWED_EXTENSIONS: Set[str] = {".jsonl", ".json", ".csv", ".txt", ".parquet", ".md"}
    MAX_FILE_SIZE_BYTES: int = 100 * 1024 * 1024  # 100 MB safe limit for workstation

    def __init__(
        self,
        min_content_length: int = 5,
        max_content_length: int = 1_000_000,
        allowed_extensions: Optional[Set[str]] = None,
        max_file_size: Optional[int] = None,
    ) -> None:
        self.min_content_length = min_content_length
        self.max_content_length = max_content_length
        self.allowed_extensions = allowed_extensions or self.ALLOWED_EXTENSIONS
        self.max_file_size = max_file_size or self.MAX_FILE_SIZE_BYTES

    def compute_sha256(self, file_path: Union[str, Path]) -> str:
        """Compute SHA-256 checksum of file safely in chunks."""
        hasher = hashlib.sha256()
        with open(file_path, "rb") as f:
            while chunk := f.read(65536):
                hasher.update(chunk)
        return hasher.hexdigest()

    def validate_file(self, file_path: Union[str, Path]) -> ValidationReport:
        """Perform comprehensive file-level and record-level validation on a dataset file.

        Args:
            file_path: Path to dataset file.

        Returns:
            ValidationReport detailing validation outcomes.
        """
        path = Path(file_path)
        errors: List[str] = []
        warnings: List[str] = []

        if not path.is_file():
            return ValidationReport(
                is_valid=False,
                total_records=0,
                valid_records=0,
                invalid_records=0,
                errors=[f"File not found: {path}"],
            )

        # Check extension
        if path.suffix.lower() not in self.allowed_extensions:
            errors.append(
                f"Disallowed file extension '{path.suffix}'. Allowed: {sorted(self.allowed_extensions)}"
            )

        # Check file size limit
        file_size = path.stat().st_size
        if file_size == 0:
            errors.append(f"File is completely empty: {path}")
        elif file_size > self.max_file_size:
            errors.append(
                f"File size {file_size} bytes exceeds maximum allowed limit {self.max_file_size} bytes."
            )

        if errors:
            return ValidationReport(
                is_valid=False,
                total_records=0,
                valid_records=0,
                invalid_records=0,
                errors=errors,
            )

        checksum = self.compute_sha256(path)

        # Check encoding and records for JSONL / text formats
        total_records = 0
        valid_records = 0
        invalid_records = 0

        if path.suffix.lower() == ".jsonl":
            try:
                with open(path, "r", encoding="utf-8") as f:
                    for line_num, line in enumerate(f, start=1):
                        total_records += 1
                        stripped = line.strip()
                        if not stripped:
                            invalid_records += 1
                            errors.append(f"Line {line_num}: Empty record line.")
                            continue
                        try:
                            record = json.loads(stripped)
                        except json.JSONDecodeError as e:
                            invalid_records += 1
                            errors.append(f"Line {line_num}: Corrupted JSON: {e}")
                            continue

                        # Schema check
                        content = record.get("content", record.get("text"))
                        if not content or not isinstance(content, str):
                            invalid_records += 1
                            errors.append(f"Line {line_num}: Missing or non-string 'content' field.")
                            continue

                        c_len = len(content.strip())
                        if c_len < self.min_content_length:
                            invalid_records += 1
                            errors.append(
                                f"Line {line_num}: Content length {c_len} below minimum {self.min_content_length}."
                            )
                            continue

                        if c_len > self.max_content_length:
                            warnings.append(
                                f"Line {line_num}: Content length {c_len} exceeds recommended maximum {self.max_content_length}."
                            )

                        valid_records += 1

            except UnicodeDecodeError as e:
                errors.append(f"File failed UTF-8 encoding check: {e}")
                return ValidationReport(
                    is_valid=False,
                    total_records=total_records,
                    valid_records=valid_records,
                    invalid_records=invalid_records,
                    errors=errors,
                    file_checksum=checksum,
                )
        else:
            # Plain text single record
            try:
                content = path.read_text(encoding="utf-8")
                total_records = 1
                if len(content.strip()) >= self.min_content_length:
                    valid_records = 1
                else:
                    invalid_records = 1
                    errors.append(f"File content below minimum length {self.min_content_length}.")
            except UnicodeDecodeError as e:
                errors.append(f"File failed UTF-8 encoding check: {e}")

        is_valid = len(errors) == 0 and valid_records > 0
        return ValidationReport(
            is_valid=is_valid,
            total_records=total_records,
            valid_records=valid_records,
            invalid_records=invalid_records,
            errors=errors,
            warnings=warnings,
            file_checksum=checksum,
        )
